import { spawnSync } from "node:child_process";
import { readFile, writeFile } from "node:fs/promises";

const input = "../../web/tests/fixtures/openapi.snapshot.json";
const output = "src/generated-types.ts";
const result = spawnSync(
  "openapi-typescript",
  [input, "-o", output],
  { stdio: "inherit", shell: process.platform === "win32" },
);
if (result.error) throw result.error;
if (result.status !== 0) process.exit(result.status ?? 1);

const header = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 *
 * @generated
 * @provenance tool=openapi-typescript toolVersion=^7.4.3
 * @provenance source=web/tests/fixtures/openapi.snapshot.json
 * @provenance package=@talos-protocol/sdk
 * @see packages/sdk/src/provenance.ts for runtime-accessible provenance
 * @see packages/sdk/TYPE_GENERATION_POLICY.md for regeneration instructions
 */
`;
const generated = await readFile(output, "utf8");
const normalized = generated.replace(/^\/\*[\s\S]*?\*\/\r?\n/, header);
await writeFile(output, normalized);